(()=>{'use strict';
const Geo=window.FLIGHT_WEATHER_GEO;const el=id=>document.getElementById(id),fields={wind:['wind_speed_10m','m/s',0,15],gust:['wind_gusts_10m','m/s',0,20],cloud:['cloud_cover','%',0,100],rain:['precipitation','mm/h',0,5]},fmt=t=>new Date(t).toLocaleString('en-GB',{timeZone:'Europe/London'});
let rm,radarLaunch,radarSequence=0,radarPending=false,radarRequestSite='',radarReport=null,radarState={status:'not-requested',retrievedAt:null,frameTime:null};
const radarDetails=el('radareligible')?.closest('details'),radarPanel=document.createElement('section');radarPanel.id='recent-radar-panel';radarPanel.className='weather-phase recent-radar-panel';radarPanel.setAttribute('aria-labelledby','radartitle');const radarTitle=document.createElement('h3');radarTitle.id='radartitle';radarTitle.textContent='Recent rain radar';radarPanel.append(radarTitle);if(radarDetails){for(const node of Array.from(radarDetails.childNodes))if(node.nodeType!==1||node.tagName!=='SUMMARY')radarPanel.append(node);radarDetails.remove();}el('weathercard').append(radarPanel);el('radarmap').hidden=false;el('radarhide').textContent='Clear radar imagery';el('radarhide').setAttribute('aria-label','Clear radar imagery; keep radar panel visible');
function radarStatus(text,status){el('radarstatus').textContent=text;if(status)radarState.status=status;el('radarstatus').dataset.radarState=radarState.status;}
function radarSite(){return site?site.lat.toFixed(6)+','+site.lon.toFixed(6):'';}
window.flightRadarStatus=()=>({...radarState,site:radarRequestSite,pending:radarPending,eligible:el('radareligible').checked});
let wm,marks,launch,radar,coverage,grid=null,sequence=0,abort=null,radarFrames=[],radarHost='',fetched=0;
window.flightWeatherEndpoint=p=>'https://api.open-meteo.com/v1/forecast?'+new URLSearchParams(p);
function init(){if(!site||!window.L)return false;if(!wm){wm=L.map('weathermap',{crs:L.CRS.EPSG3857}).setView([site.lat,site.lon],10);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors'}).addTo(wm);marks=L.layerGroup().addTo(wm);L.control.scale({imperial:false}).addTo(wm);}wm.invalidateSize();return true;}
function clear(){grid=null;el('wxpositions').textContent='Model point coordinates will appear after loading.';marks?.clearLayers();el('wxmapstatus').textContent='Select a site and load the weather map.';}
function clearRadar(message){radarSequence++;radarPending=false;if(radar)rm?.removeLayer(radar);if(coverage)rm?.removeLayer(coverage);radar=coverage=null;radarFrames=[];radarReport=null;el('radarframe').replaceChildren();el('radarmap').hidden=false;radarState={status:'not-requested',retrievedAt:null,frameTime:null};radarStatus((message||'Radar not loaded for this site.')+(!navigator.onLine?' OFFLINE — radar cannot refresh.':''),navigator.onLine?'not-requested':'offline');}
function selected(){return window.FLIGHT_AIRSPACE.londonStart(el('date').value,el('hour').value);}
function colour(v,max){return `hsl(${220-Math.min(1,Math.max(0,v/max))*220} 70% 48%)`;}
function legend(){const [,unit,,max]=fields[el('wxlayer').value],name=el('wxlayer').selectedOptions[0].text,wrap=el('wxlegend');wrap.replaceChildren();const title=document.createElement('strong');title.textContent=name+' · '+unit;const bar=document.createElement('div');bar.className='wxcolourbar';bar.style.background='linear-gradient(to right, '+Array.from({length:45},(_,i)=>colour(max*i/44,max)+' '+(100*i/44)+'%').join(', ')+')';bar.setAttribute('aria-hidden','true');const ticks=document.createElement('div');ticks.className='wxlegendticks';for(let i=0;i<=4;i++){const tick=document.createElement('span'),v=max*i/4;tick.style.left=(i*25)+'%';tick.textContent=String(Number(v.toFixed(2)))+(i===4&&unit!=='%'?'+':'');ticks.append(tick);}const note=document.createElement('p');note.className='hint';note.textContent='Point colours use this scale. '+(unit==='%'?'Cloud cover spans 0–100%.':'Values at or above '+max+' '+unit+' share the final red colour.')+' Tap a point for its exact value. This scale does not indicate flight safety.';wrap.append(title,bar,ticks,note);}
function draw(){if(!init()||!grid)return;marks.clearLayers();const t=selected();if(t===null){el('wxmapstatus').textContent='Select an unambiguous valid date/hour.';return;}const [field,unit,min,max]=fields[el('wxlayer').value],i=grid[0].hourly.time.indexOf(t/1000);if(i<0){el('wxmapstatus').textContent='No map forecast for the selected hour. Refresh or choose a time within the forecast range.';return;}
let count=0;const plotted=Geo.groups(grid);for(const point of plotted){const rows=point.samples.map(g=>({g,value:g.hourly[field]?.[g.hourly.time.indexOf(t/1000)]})).filter(r=>typeof r.value==='number'&&Number.isFinite(r.value));if(!rows.length)continue;count++;const value=Math.max(...rows.map(r=>r.value)),c=colour(value,max),m=L.circleMarker(Geo.leaflet(point),{radius:10,color:c,fillColor:c,fillOpacity:1,weight:2}).addTo(marks),box=document.createElement('div'),title=document.createElement('strong');title.textContent=`Returned model location · ${point.lat.toFixed(6)}° latitude, ${point.lon.toFixed(6)}° longitude (WGS84)`;box.append(title);const note=document.createElement('p');note.textContent=`${el('wxlayer').selectedOptions[0].text} · ${fmt(t)}. ${rows.length} requested sample(s) at this returned location. Colour represents the highest of the listed values when samples share a location; no averaging or positional jitter is applied.`;box.append(note);for(const {g,value:v}of rows){const p=document.createElement('p');p.textContent=`${v.toFixed(1)} ${unit} · requested ${g.requested.lat.toFixed(6)}, ${g.requested.lon.toFixed(6)} · returned-location offset ${(g.displacement/1000).toFixed(2)} km.`;if(field==='wind_speed_10m'){const d=g.hourly.wind_direction_10m?.[g.hourly.time.indexOf(t/1000)];if(typeof d==='number')p.textContent+=` Wind from ${d.toFixed(0)}°.`;}box.append(p);}m.bindPopup(box);m.bindTooltip(`${value.toFixed(1)} ${unit} · ${point.lat.toFixed(5)}, ${point.lon.toFixed(5)}`);}
el('wxpositions').textContent=`Launch: ${site.lat.toFixed(6)}° latitude, ${site.lon.toFixed(6)}° longitude · WGS84 decimal degrees. ${grid.length} requested samples → ${plotted.length} distinct returned model locations. Largest request-to-model offset: ${(Math.max(...grid.map(g=>g.displacement))/1000).toFixed(2)} km. Points mark returned model locations; the launch pin is separate. WGS84 lat/lon is projected by Leaflet onto the Web Mercator (EPSG:3857) basemap. No British National Grid conversion is needed.`;

legend();
el('wxmapstatus').textContent=`MODEL FORECAST · ${fmt(t)} Europe/London · ${count} distinct model locations · retrieved ${fmt(fetched)}. Retrieval time is not model issue time. Open-Meteo public endpoint.`;}
async function load(){if(!site){el('wxmapstatus').textContent='Select a flight site first.';return;}if(!navigator.onLine){clear();el('wxmapstatus').textContent='Weather map unavailable offline.';return;}const seq=++sequence;abort?.abort();abort=new AbortController();clear();if(!init()){el('wxmapstatus').textContent='Map library unavailable. Use the weather charts and data.';return;}if(launch)wm.removeLayer(launch);launch=L.marker([site.lat,site.lon]).addTo(wm).bindPopup('Flight launch · WGS84 latitude '+site.lat.toFixed(6)+', longitude '+site.lon.toFixed(6));wm.setView([site.lat,site.lon],10);el('wxmapstatus').textContent='Loading regional model forecast…';const requested=Geo.samples(site),lat=requested.map(p=>p.lat.toFixed(6)),lon=requested.map(p=>p.lon.toFixed(6));
const p=new URLSearchParams({latitude:lat.join(','),longitude:lon.join(','),hourly:'wind_speed_10m,wind_direction_10m,wind_gusts_10m,cloud_cover,precipitation',wind_speed_unit:'ms',timeformat:'unixtime',timezone:'GMT',forecast_days:'7',cell_selection:'nearest'});try{const r=await fetch(window.flightWeatherEndpoint(p),{signal:AbortSignal.any([abort.signal,AbortSignal.timeout(20000)]),cache:'no-store'});if(!r.ok)throw Error('Forecast HTTP '+r.status);const j=await r.json();if(seq!==sequence)return;if(!Array.isArray(j)||j.length!==25||j.some(g=>!g.hourly?.time?.length||g.hourly_units?.wind_speed_10m!=='m/s'))throw Error('Incomplete map response');grid=Geo.attach(j,requested);fetched=Date.now();wm.fitBounds(L.latLngBounds([Geo.leaflet(site),...grid.map(g=>Geo.leaflet({lat:g.latitude,lon:g.longitude}))]),{padding:[25,25],maxZoom:11});draw();}catch(e){if(seq===sequence){grid=null;marks.clearLayers();el('wxmapstatus').textContent=e.name==='AbortError'?'Map request cancelled. Refresh to retry.':'Map forecast unavailable. Check connection and provider availability, then retry. No sample data displayed. Returned coordinates must be valid WGS84 and within a 30 km sanity-check distance of each request.';}}}
function initRadar(){if(!site||!window.L)return false;el('radarmap').hidden=false;if(!rm){rm=L.map('radarmap',{crs:L.CRS.EPSG3857}).setView([site.lat,site.lon],7);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors'}).addTo(rm);L.control.scale({imperial:false}).addTo(rm);}rm.invalidateSize();rm.setView([site.lat,site.lon],7);if(radarLaunch)rm.removeLayer(radarLaunch);radarLaunch=L.marker([site.lat,site.lon]).addTo(rm).bindPopup('Flight launch · WGS84 '+site.lat.toFixed(6)+', '+site.lon.toFixed(6));return true;}
async function loadRadar(){if(!el('radareligible').checked){radarStatus('Radar not loaded: confirm eligibility under the provider terms. The radar panel remains available.','ineligible');return;}if(!site){radarStatus('Radar not loaded: select a flight site.','no-site');return;}if(!navigator.onLine){radarStatus('OFFLINE — recent radar cannot refresh. Any retained imagery is historical; do not infer dry conditions.','offline');return;}if(!initRadar()){radarStatus('Radar map unavailable: map library did not load. No conclusion about rain can be drawn.','unavailable');return;}if(radarPending)return;const seq=++radarSequence;radarRequestSite=radarSite();radarPending=true;radarStatus('Loading latest available recent radar frame…','pending');try{const r=await fetch('https://api.rainviewer.com/public/weather-maps.json',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Radar metadata HTTP '+r.status);const j=await r.json();if(seq!==radarSequence||!el('radareligible').checked||radarRequestSite!==radarSite())return;if(j.host!=='https://tilecache.rainviewer.com'||!Array.isArray(j.radar?.past))throw Error('Unexpected radar metadata');const frames=j.radar.past.filter(f=>Number.isFinite(f.time)&&/^\/v2\/radar\/[a-fA-F0-9]+$/.test(f.path)).sort((a,b)=>a.time-b.time);if(!frames.length)throw Error('No recent frames supplied');radarHost=j.host;radarFrames=frames;radarState.refreshFailed=false;radarState.retrievedAt=new Date().toISOString();el('radarframe').replaceChildren(...radarFrames.map((f,i)=>{const o=document.createElement('option');o.value=i;o.textContent=fmt(f.time*1000);return o;}));el('radarframe').value=String(radarFrames.length-1);showRadar();}catch(e){if(seq===radarSequence){radarReport=null;radarState.refreshFailed=true;radarStatus('Radar refresh failed: '+e.message+'. '+(radar?'Previously loaded imagery is retained as HISTORICAL / UNVERIFIED, not a current check. ':'No radar imagery available. ')+'No conclusion about rain can be drawn. Use Load / refresh to retry.','failed');}}finally{if(seq===radarSequence)radarPending=false;}}
function hideRadar(){clearRadar('Radar imagery cleared. The radar panel remains visible; use Load / refresh to show the latest available frame.');}
function autoRadar(){if(!el('radareligible').checked){radarStatus('Radar not loaded: confirm eligible use under the RainViewer terms.','ineligible');return;}if(!site){radarStatus('Radar not loaded: select a flight site.','no-site');return;}if(radarRequestSite===radarSite())return;loadRadar();}

function showRadar(){if(!navigator.onLine){radarStatus('OFFLINE — retained radar imagery is historical / unverified; no dry-weather inference is possible.','offline');return;}if(!site||!el('radareligible').checked||!initRadar())return;if(radar)rm.removeLayer(radar);if(coverage)rm.removeLayer(coverage);const f=radarFrames[Number(el('radarframe').value)];if(!f)return;const layer=L.tileLayer(`${radarHost}${f.path}/256/{z}/{x}/{y}/2/0_0.png`,{maxNativeZoom:7,maxZoom:18,opacity:.75,attribution:'Weather data by <a href="https://www.rainviewer.com/">RainViewer</a>'});radar=layer;let loaded=0,failed=0,maskFailed=false;const description=()=>`RECENT RADAR · selected frame generated ${fmt(f.time*1000)} Europe/London${Date.now()-f.time*1000>30*60000?' · STALE':''}. Observation mosaic, not a forecast for your flight time. Black shading: no radar coverage; transparent areas can also mean missing data.`;const reportSequence=radarSequence,report=()=>{if(radar!==layer||reportSequence!==radarSequence)return;radarState.frameTime=new Date(f.time*1000).toISOString();radarStatus((radarState.refreshFailed?'LATEST REFRESH FAILED — retained collection is unverified. ':'')+description()+' '+(maskFailed?'Coverage mask failed — do not infer coverage or dry conditions. ':'')+(failed?'WARNING: '+failed+' radar tile(s) failed — coverage incomplete.':loaded?'Radar imagery loaded: '+loaded+' tiles.':'Loading selected frame imagery…'),radarState.refreshFailed?'failed':failed||maskFailed?'incomplete':Date.now()-f.time*1000>30*60000?'stale':loaded?'loaded':'pending');};radarReport=report;layer.on('tileload',()=>{loaded++;report();});layer.on('tileerror',()=>{failed++;report();});report();layer.addTo(rm);coverage=L.tileLayer(`${radarHost}/v2/coverage/0/256/{z}/{x}/{y}/0/0_0.png`,{maxNativeZoom:7,maxZoom:18,opacity:.45});coverage.on('tileerror',()=>{if(radar===layer){maskFailed=true;report();}});coverage.addTo(rm);}
el('wxload').onclick=load;el('wxlayer').onchange=()=>{legend();draw();};legend();el('weather-map-panel').addEventListener('toggle',()=>{if(el('weather-map-panel').open){init();if(!grid)load();}});for(const id of ['date','hour'])el(id).addEventListener('change',draw);const before=select;select=function(...args){const previous=radarSite();sequence++;abort?.abort();clear();before(...args);if(previous!==radarSite()){clearRadar();radarRequestSite='';autoRadar();}if(el('weather-map-panel').open)load();};
el('radareligible').onchange=()=>{radarRequestSite='';if(el('radareligible').checked)loadRadar();else{clearRadar('Radar not loaded: provider eligibility has not been confirmed.');radarStatus(el('radarstatus').textContent,'ineligible');}};el('radarload').onclick=loadRadar;el('radarframe').onchange=showRadar;el('radarhide').onclick=hideRadar;window.addEventListener('offline',()=>{sequence++;abort?.abort();clear();radarSequence++;radarPending=false;radarReport=null;radarStatus('OFFLINE — radar cannot refresh. '+(radar?'Retained imagery is historical / unverified. ':'No radar imagery available. ')+'Do not infer dry conditions.','offline');el('wxmapstatus').textContent='Offline — live weather map unavailable.';});window.addEventListener('online',()=>{radarRequestSite='';autoRadar();});setInterval(()=>{if(radarReport&&!radarPending&&navigator.onLine)radarReport();},60000);autoRadar();
})();
